// Package: Microsoft.SemanticKernel, Microsoft.Extensions.AI, System.Text.Json

using Microsoft.SemanticKernel;
using Microsoft.Extensions.AI;
using System.Text.Json;
using System.ComponentModel;

public enum ToolRiskLevel
{
    ReadOnly,
    Write,
    Destructive
}

public class ApprovalPolicy
{
    public bool RequiresApproval(string toolName)
    {
        // Risk-based approval: writes and destructive actions require approval
        var risk = toolName.ToLowerInvariant() switch
        {
            var name when name.Contains("send") || name.Contains("delete") => ToolRiskLevel.Destructive,
            var name when name.Contains("update") || name.Contains("create") => ToolRiskLevel.Write,
            _ => ToolRiskLevel.ReadOnly
        };

        return risk != ToolRiskLevel.ReadOnly;
    }
}

public class ApprovalRequest
{
    public string Id { get; set; } = Guid.NewGuid().ToString();
    public string ToolCallId { get; set; } = string.Empty;
    public string FunctionName { get; set; } = string.Empty;
    public string Arguments { get; set; } = string.Empty;
    public string RequesterId { get; set; } = string.Empty;
    public DateTimeOffset RequestedAt { get; set; } = DateTimeOffset.UtcNow;
    public bool IsApproved { get; set; }
    public string? ApproverId { get; set; }
    public DateTimeOffset? DecidedAt { get; set; }
}

public interface IApprovalStore
{
    Task<ApprovalRequest> RequestApprovalAsync(string toolName, string arguments, string requesterId, CancellationToken ct);
    Task RecordDecisionAsync(string requestId, bool approved, string approverId, CancellationToken ct);
}

public class InMemoryApprovalStore : IApprovalStore
{
    private readonly Dictionary<string, ApprovalRequest> _store = new();

    public Task<ApprovalRequest> RequestApprovalAsync(string toolName, string arguments, string requesterId, CancellationToken ct)
    {
        var request = new ApprovalRequest
        {
            ToolCallId = Guid.NewGuid().ToString(),
            FunctionName = toolName,
            Arguments = JsonSerializer.Serialize(arguments),
            RequesterId = requesterId
        };

        _store[request.Id] = request;
        return Task.FromResult(request);
    }

    public Task RecordDecisionAsync(string requestId, bool approved, string approverId, CancellationToken ct)
    {
        if (_store.TryGetValue(requestId, out var request))
        {
            request.IsApproved = approved;
            request.ApproverId = approverId;
            request.DecidedAt = DateTimeOffset.UtcNow;
        }
        return Task.CompletedTask;
    }
}

public class ApprovalToolDecorator
{
    private readonly IApprovalStore _approvalStore;
    private readonly ApprovalPolicy _policy;
    private readonly ToolExecutor _inner;

    public ApprovalToolDecorator(IApprovalStore approvalStore, ApprovalPolicy policy, Kernel kernel)
    {
        _approvalStore = approvalStore;
        _policy = policy;
        _inner = new ToolExecutor(kernel);
    }

    public async Task<ToolResult> ExecuteWithApprovalAsync(
        string toolName,
        string argumentsJson,
        string sessionUserId,
        CancellationToken ct = default)
    {
        if (_policy.RequiresApproval(toolName))
        {
            var approval = await _approvalStore.RequestApprovalAsync(
                toolName,
                argumentsJson,
                requesterId: sessionUserId,
                ct);

            // Simulate waiting for human decision
            // In production, this would be a webhook or polling mechanism
            await Task.Delay(1000, ct);

            // Default to approved for demo; real system would check approval.IsApproved
            if (!approval.IsApproved)
            {
                return ToolResult.Cancelled("Approval denied by user.");
            }

            await _approvalStore.RecordDecisionAsync(approval.Id, true, "human-reviewer", ct);
        }

        return await _inner.ExecuteByJsonAsync(toolName, argumentsJson, ct);
    }
}

public class ToolResult
{
    public string CallId { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public bool IsError { get; set; }
    public string? ErrorMessage { get; set; }

    public static ToolResult Cancelled(string reason) => new()
    {
        Content = reason,
        IsError = true
    };
}

